import json
import re
from docx import Document

TEMPLATE_PATH = '/root/offer_letter_template.docx'
DATA_PATH = '/root/employee_data.json'
OUTPUT_PATH = '/root/offer_letter_filled.docx'

with open(DATA_PATH, 'r', encoding='utf-8') as f:
    data = json.load(f)

def should_include_relocation(data_dict):
    val = str(data_dict.get('RELOCATION_PACKAGE', '')).strip().lower()
    return val in {'yes', 'y', 'true', '1'}

INCLUDE_RELOCATION = should_include_relocation(data)

PLACEHOLDER_RE = re.compile(r'\{\{([A-Z0-9_]+)\}\}')


def replace_placeholders(text):
    def repl(match):
        key = match.group(1)
        if key in data:
            return str(data[key])
        return match.group(0)
    return PLACEHOLDER_RE.sub(repl, text)


def handle_conditional(text):
    if '{{IF_RELOCATION}}' in text or '{{END_IF_RELOCATION}}' in text:
        if INCLUDE_RELOCATION:
            text = text.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')
        else:
            text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}', '', text)
    return text


def set_paragraph_text(paragraph, new_text):
    runs = paragraph.runs
    if runs:
        runs[0].text = new_text
        for run in runs[1:]:
            run.text = ''
    else:
        if new_text:
            paragraph.add_run(new_text)


def process_paragraph(paragraph):
    original = paragraph.text
    if not original:
        return
    text = handle_conditional(original)
    text = replace_placeholders(text)
    if text != original:
        set_paragraph_text(paragraph, text)


def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                process_paragraph(para)
            for nested in cell.tables:
                process_table(nested)


def process_document(doc):
    for para in doc.paragraphs:
        process_paragraph(para)
    for table in doc.tables:
        process_table(table)
    for section in doc.sections:
        for para in section.header.paragraphs:
            process_paragraph(para)
        for para in section.footer.paragraphs:
            process_paragraph(para)


doc = Document(TEMPLATE_PATH)
process_document(doc)
doc.save(OUTPUT_PATH)

print(f"Wrote {OUTPUT_PATH}")
